      "html": "    <section class=\"section-6\" aria-label=\"Destaque do produto com texto\">\n      <picture>\n        <source media=\"(max-width: 760px)\"\n          srcset=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/section-49-2.png\"\n          width=\"780\" height=\"400\">\n        <img class=\"section-6__image\"\n          src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/section-49-1.png\"\n          alt=\"Caderno Funny Cat com estampa de gatinhos, capa colorida e espiral\" width=\"1600\" height=\"650\"\n          loading=\"lazy\" fetchpriority=\"high\" decoding=\"async\">\n      </picture>\n      <div class=\"section-6__content\">\n        <h2 class=\"section-6__title\">Caderno Funny Cat</h2>\n        <p class=\"section-6__description\">Organize seus estudos com fofura e estilo!</p>\n      </div>\n    </section>",
      "css": "    <style>\n        /* ===== HERO SECTION — VARIÁVEIS ===== */\n        .section-6 {\n            --pos-y: 50%;\n            --pos-x: 7%;\n            --color-title: #ffe178;\n            --bg-box: rgba(0, 0, 0, 0.33);\n\n            width: 100%;\n            position: relative;\n            border-radius: 20px;\n            overflow: hidden;\n        }\n\n        /* ===== IMAGEM ===== */\n        .section-6__image {\n            width: 100%;\n            height: auto;\n            display: block;\n            border-radius: 20px;\n        }\n\n        /* ===== CONTEÚDO SOBREPOSTO ===== */\n        .section-6__content {\n            position: absolute;\n            top: var(--pos-y);\n            left: clamp(1%, var(--pos-x), 100%);\n            transform: translateY(-50%);\n            max-width: min(40%, 480px);\n            z-index: 10;\n            background-color: var(--bg-box);\n            padding: clamp(12px, 2vw, 20px);\n            border-radius: 15px;\n            backdrop-filter: blur(4px);\n        }\n\n        .section-6__title {\n            font-size: clamp(1.4rem, 3.5vw, 2.6rem);\n            color: var(--color-title);\n            margin: 0 0 10px;\n            line-height: 1.2;\n            text-shadow: 2px 2px 6px rgba(0, 0, 0, 0.4);\n            font-weight: 800;\n        }\n\n        .section-6__description {\n            font-size: clamp(0.95rem, 2vw, 1.4rem);\n            color: #fff;\n            margin: 0 0 24px;\n            line-height: 1.5;\n            text-shadow: 1px 1px 4px rgba(0, 0, 0, 0.35);\n        }\n\n        /* ===== MOBILE ===== */\n        @media (max-width: 760px) {\n            .section-6__ {\n                border-radius: 0;\n            }\n\n            .section-6__content {\n                position: static;\n                transform: none;\n                max-width: 100%;\n                padding: 24px 20px 16px 20px;\n                background: transparent;\n                backdrop-filter: none;\n                text-align: center;\n            }\n\n            .section-6__title {\n                font-size: 1.8rem;\n                color: #333;\n                text-shadow: none;\n            }\n\n            .section-6__description {\n                margin-bottom: 0;\n                font-size: 1.1rem;\n                color: #555;\n                text-shadow: none;\n            }\n\n            .section-6__image {\n                width: 95%;\n                margin: auto;\n                height: auto;\n                display: block;\n                border-radius: 20px;\n            }\n        }\n\n        @media (max-width: 480px) {\n            .section-6__title {\n                font-size: 1.5rem;\n            }\n\n            .section-6__description {\n                font-size: 1rem;\n            }\n        }\n    </style>"
