      "html": "    <section class=\"wrapper-section-8\" aria-labelledby=\"section-8-title\">\n      <div class=\"text-col-section-8\">\n        <img src=\"https://cdn-icons-png.flaticon.com/512/894/894565.png\" class=\"brand-icon-section-8\"\n          alt=\"Imagem representativa\" width=\"60\" height=\"60\" loading=\"lazy\" />\n        <h2 id=\"section-8-title\" class=\"title-section-8\">\n          A Lenda dos Sete Mares\n        </h2>\n        <p class=\"desc-section-8\">\n          Capitan Cortez não é apenas um rum, é um convite à descoberta. Inspirado\n          nos diários de bordo dos grandes navegadores, nossa receita busca capturar\n          a glória da tradição em cada garrafa. Uma homenagem àqueles que ousam ir\n          além do horizonte.\n        </p>\n      </div>\n      <!-- Imagem Principal-->\n      <div class=\"image-col-section-8\">\n        <img src=\"C:UsersygorqDownloadscabo-flexivel-corfio-1-5mm-bobina-vermelho-4203788-01.jpg\"\n          class=\"bg-image-section-8\" alt=\"Imagem representativa\" width=\"800\" height=\"600\" loading=\"lazy\" />\n      </div>\n    </section>",
      "css": "  <style>\n    /* ===== Section-8 ===== */\n    .wrapper-section-8 {\n      display: flex;\n      flex-wrap: wrap;\n      width: 100%;\n      background-color: #f8f8f8;\n      min-height: 28rem;\n    }\n\n    .text-col-section-8 {\n      flex: 1 1 18.75rem;\n      padding: 2.5rem 1.25rem;\n      display: flex;\n      flex-direction: column;\n      justify-content: center;\n      align-items: center;\n      text-align: center;\n      gap: 1.25rem;\n    }\n\n    .image-col-section-8 {\n      flex: 1 1 18.75rem;\n      position: relative;\n    }\n\n    .brand-icon-section-8 {\n      width: 3.75rem;\n      height: auto;\n      opacity: 0.8;\n      display: block;\n    }\n\n    .title-section-8 {\n      font-size: clamp(22px, 3.2vw, 38px);\n      font-weight: 700;\n      line-height: 1.2;\n      text-align: center;\n    }\n\n    .desc-section-8 {\n      font-size: clamp(14px, 1.4vw, 22px);\n      color: #1b1b1b;\n      line-height: 28px;\n    }\n\n\n\n\n\n\n    @media (max-width: 1060px) {\n\n      .title-section-8 h1 {\n        font-size: 3.8vw;\n      }\n\n      .desc-section-8 {\n        font-size: 1.8vw;\n      }\n    }\n\n    @media (max-width: 960px) {\n\n      .title-section-8 h1 {\n        font-size: 4.3vw;\n      }\n\n      .desc-section-8 {\n        font-size: 2vw;\n      }\n\n    }\n\n    @media (max-width: 730px) {\n\n      .title-section-8 h1 {\n        font-size: 5vw;\n      }\n\n      .desc-section-8 {\n        font-size: 2.9vw;\n      }\n    }\n\n    @media (max-width: 500px) {\n      .title-section-8 h1 {\n        font-size: 6vw;\n      }\n\n      .desc-section-8 {\n        font-size: 3.5vw;\n      }\n\n    }\n\n    @media (max-width: 420px) {\n      .title-section-8 h1 {\n        font-size: 7vw;\n      }\n\n      .desc-section-8 {\n        font-size: 4vw;\n      }\n    }\n\n\n\n\n    .arrow-icon-section-8 {\n      font-size: 1rem;\n      line-height: 1;\n      display: inline-block;\n      transition: transform 0.3s;\n    }\n\n    .cta-link-section-8:hover .arrow-icon-section-8 {\n      transform: translateX(4px);\n    }\n\n    .bg-image-section-8 {\n      width: 95%;\n      height: 95%;\n      margin: 0.5rem;\n      border-radius: 15px;\n      object-fit: cover;\n      display: block;\n      min-height: 18.75rem;\n    }\n\n    @media (min-width: 768px) {\n      .text-col-section-8 {\n        padding: 1.5rem 1.25rem 0.7rem;\n      }\n\n      .reverse-desktop-section-8 {\n        flex-direction: row-reverse;\n      }\n    }\n\n    @media (max-width: 720px) {\n      .wrapper-section-8 {\n        flex-direction: column-reverse;\n      }\n\n      .reverse-mobile-section-8 {\n        flex-direction: column;\n      }\n\n      .bg-image-section-8 {\n        width: 90%;\n        height: 100%;\n        object-fit: cover;\n        display: block;\n        min-height: 18.75rem;\n        max-width: 95%;\n        margin: 0.6rem auto;\n        border-radius: 10px;\n        aspect-ratio: 26 / 17;\n      }\n    }\n  </style>"
