      "html": "        <section class=\"section-11\" aria-labelledby=\"section-11-title\">\n            <div class=\"section-11-container\">\n                <header class=\"section-11__header\">\n                    <h2 class=\"section-11__title\" id=\"section-11-title\">Diferenciais que garantem uma instalação superior</h2>\n                </header>\n                <ul class=\"section-11__grid\" role=\"list\">\n                    <li class=\"section-11__item\">\n                        <figure class=\"section-11__figure\">\n                            <img class=\"section-11__image\" src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/corfio/4203786_03-1.png\" alt=\"Ícone de formato universitário\"\n                                width=\"74\" height=\"74\" loading=\"lazy\">\n                        </figure>\n                        <h3 class=\"section-11__name\">Flexibilidade Classe 4/5</h3>\n                        <p class=\"section-11__value\">Cobre de têmpera mole que desliza facilmente pelos eletrodutos, economizando tempo e esforço na instalação</p>\n                    </li>\n                </ul>\n            </div>\n        </section>",
      "css": "    <style>\n        .section-11-container {\n            padding-bottom: 3rem;\n            padding-left: 1rem;\n            padding-right: 1rem;\n        }\n\n        @media (min-width: 576px) {\n            .section-11-container {\n                max-width: 576px;\n                margin-inline: auto;\n            }\n        }\n\n        @media (min-width: 768px) {\n            .section-11-container {\n                max-width: 768px;\n            }\n        }\n\n        @media (min-width: 992px) {\n            .section-11-container {\n                max-width: 992px;\n            }\n        }\n\n        @media (min-width: 1200px) {\n            .section-11-container {\n                max-width: 1200px;\n            }\n        }\n\n        @media (min-width: 1536px) {\n            .section-11-container {\n                max-width: 1536px;\n            }\n        }\n\n        .section-11__header {\n            text-align: center;\n            margin-bottom: 2rem;\n        }\n\n        .section-11__title {\n            font-size: 32px;\n            font-weight: 900;\n            color: #1a1a1a;\n            margin: 0;\n            line-height: 1.25;\n        }\n\n        .section-11__grid {\n            display: grid;\n            grid-template-columns: repeat(2, minmax(0, 1fr));\n            gap: 1rem;\n            list-style: none;\n            margin: 0;\n            padding: 0;\n        }\n\n        @media (min-width: 768px) {\n            .section-11__grid {\n                grid-template-columns: repeat(3, minmax(0, 1fr));\n            }\n        }\n\n        @media (min-width: 992px) {\n            .section-11__grid {\n                grid-template-columns: repeat(5, minmax(0, 1fr));\n            }\n        }\n\n        .section-11__item {\n            background: #fff;\n            border: 0.5px solid rgba(0, 0, 0, 0.1);\n            border-radius: 12px;\n            padding: 1.5rem 1rem;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            text-align: center;\n            gap: 0.75rem;\n            transition: border-color 0.2s;\n        }\n\n        .section-11__item:hover {\n            border-color: rgba(0, 0, 0, 0.22);\n        }\n\n        .section-11__figure {\n            margin: 0;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            width: 72px;\n            height: 72px;\n        }\n\n        .section-11__image {\n            width: 4.6rem;\n            height: auto;\n            display: block;\n        }\n\n        .section-11__name {\n            font-size: 0.9375rem;\n            font-weight: 500;\n            color: #1a1a1a;\n            margin: 0;\n            line-height: 1.3;\n        }\n\n        .section-11__value {\n            font-size: 0.875rem;\n            color: #666;\n            margin: 0;\n            line-height: 1.4;\n        }\n    </style>"
