      "html": "    <div class=\"section-13-container\">\n      <section class=\"section-13\" aria-label=\"Demonstração em vídeo do produto\">\n        <figure class=\"section-13__phone-wrap\">\n          <div class=\"section-13__phone\" role=\"img\" aria-label=\"Celular exibindo vídeo do produto\">\n            <div class=\"section-13__notch\" aria-hidden=\"true\"></div>\n            <!-- Tela -->\n            <div class=\"section-13__screen\">\n              <video class=\"section-13__video\" src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/risque/Lollapalooza.mov\" autoplay muted loop playsinline loading=\"lazy\"\n                aria-label=\"Demonstração em vídeo do produto\"></video>\n            </div>\n          </div>\n          <figcaption class=\"section-13__caption\">\n            <p class=\"section-13__caption-title\">Veja em ação</p>\n            <p class=\"section-13__caption-desc\">Acompanhe como o produto funciona na prática em um vídeo demonstrativo.\n            </p>\n          </figcaption>\n        </figure>\n      </section>\n    </div>",
      "css": "  <style>\n    /* ── CONTAINER UNIVERSAL ─────────────────────────── */\n    .section-13-container {\n      padding-top: 20px;\n      padding-bottom: 20px;\n    }\n\n    @media (min-width: 768px) {\n      .section-13-container {\n        padding-top: 28px;\n        padding-bottom: 28px;\n      }\n    }\n\n    @media (min-width: 1200px) {\n      .section-13-container {\n        padding-top: 25px;\n        padding-bottom: 25px;\n      }\n    }\n\n    /* ── SECTION BASE ────────────────────────────────── */\n    .section-13 {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 32px;\n    }\n\n    /* ── PHONE WRAPPER ───────────────────────────────── */\n    .section-13__phone-wrap {\n      position: relative;\n      width: 220px;\n      flex-shrink: 0;\n    }\n\n    @media (min-width: 576px) {\n      .section-13__phone-wrap {\n        width: 260px;\n      }\n    }\n\n    @media (min-width: 768px) {\n      .section-13__phone-wrap {\n        width: 300px;\n      }\n    }\n\n    @media (min-width: 992px) {\n      .section-13__phone-wrap {\n        width: 340px;\n      }\n    }\n\n    /* ── PHONE FRAME ─────────────────────────────────── */\n    .section-13__phone {\n      position: relative;\n      width: 100%;\n      aspect-ratio: 9 / 19.5;\n      background: #0d0d0d;\n      border-radius: 40px;\n      box-shadow: 0 0 0 2px #2a2a2a, 0 0 0 4px #111, 0 0 0 6px #3a3a3a, 0 0 15px 1px rgb(0 0 0 / 29%), inset 0 0 0 1px rgba(255, 255, 255, 0.06);\n      overflow: hidden;\n    }\n\n    /* Brilho lateral esquerdo */\n    .section-13__phone::before {\n      content: '';\n      position: absolute;\n      inset: 0;\n      background: linear-gradient(115deg,\n          rgba(255, 255, 255, 0.08) 0%,\n          transparent 40%);\n      border-radius: inherit;\n      z-index: 3;\n      pointer-events: none;\n    }\n\n    /* ── NOTCH / DYNAMIC ISLAND ──────────────────────── */\n    .section-13__notch {\n      position: absolute;\n      top: 14px;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 28%;\n      height: 22px;\n      background: #0d0d0d;\n      border-radius: 20px;\n      z-index: 4;\n    }\n\n    /* ── SCREEN ──────────────────────────────────────── */\n    .section-13__screen {\n      position: absolute;\n      inset: 0;\n      border-radius: 38px;\n      overflow: hidden;\n      z-index: 2;\n    }\n\n    /* ── VIDEO ───────────────────────────────────────── */\n    .section-13__video {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n      display: block;\n    }\n\n    /* ── GLOW AMBIENTAL ──────────────────────────────── */\n    .section-13__glow {\n      position: absolute;\n      bottom: -30px;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 60%;\n      height: 60px;\n      background: radial-gradient(ellipse at center, rgba(80, 140, 255, 0.25) 0%, transparent 70%);\n      pointer-events: none;\n      z-index: 0;\n      filter: blur(8px);\n    }\n\n    /* ── CAPTION ─────────────────────────────────────── */\n    .section-13__caption {\n      text-align: center;\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n      margin-top: 1.1rem;\n    }\n\n    .section-13__caption-title {\n      font-family: sans-serif;\n      font-size: 14px;\n      font-weight: 600;\n      color: #111;\n      letter-spacing: 0.02em;\n    }\n\n    .section-13__caption-desc {\n      font-family: sans-serif;\n      font-size: 13px;\n      color: #666;\n      line-height: 1.5;\n      max-width: 280px;\n    }\n\n    @media (min-width: 768px) {\n      .section-13__caption-title {\n        font-size: 15px;\n      }\n\n      .section-13__caption-desc {\n        font-size: 14px;\n        max-width: 320px;\n      }\n    }\n  </style>"
