      "css": "<style>\n  .sr-only {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    padding: 0;\n    margin: -1px;\n    overflow: hidden;\n    clip: rect(0, 0, 0, 0);\n    white-space: nowrap;\n    border: 0;\n  }\n\n   .p__end {\n    color: #8a8a8a;\n    font-family: sans-serif;\n    font-size: clamp(1rem, 2vw, 1.2rem);\n    text-wrap: pretty;\n    text-align: center;\n    padding: 40px 0;\n  }\n\n\n  .table-container-custom {\n    background-color: #fff;\n    padding: 20px;\n    border-radius: 10px;\n    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);\n    max-width: 800px;\n    width: 100%;\n    margin: 0 auto;\n    display: block;\n  }\n\n  .table-design-custom {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 0 auto;\n  }\n\n  .table-head-custom {\n    color: #fff;\n    border-radius: 10px;\n  }\n\n  .table-text-custom {\n    padding: 12px;\n    text-align: left;\n    border-bottom: 1px solid #979797;\n    font-family: sans-serif;\n  }\n\n  .table-row-custom:hover {\n    background-color: #f1f1f1;\n    filter: brightness(0.9);\n  }\n\n  .table-th-custom {\n    font-weight: bold;\n  }\n\n  .table-td-custom {\n    color: #555;\n  }\n\n  .table-tr-custom:nth-child(even) {\n    background-color: #f1f1f1;\n  }\n\n  td a {\n    color: #000;\n    font-weight: 600;\n    text-decoration: none;\n  }\n\n  td a:hover {\n    color: #e74011;\n  }\n\n  @media (prefers-contrast: more) {\n    .table-td-custom-sub {\n      color: #000;\n      font-weight: 550;\n    }\n\n    .table-td-custom-title {\n      color: #000;\n      font-weight: 700;\n    }\n\n    .p__end {\n      color: #000;\n    }\n  }\n\n  @media (max-width: 600px) {\n    .table-container-custom {\n      padding: 10px;\n    }\n\n    .table-text-custom,\n    .table-th-custom,\n    .table-td-custom {\n      padding: 8px;\n    }\n  }\n</style>"
